import{_ as a,o as r,c as e,a3 as n}from"./chunks/framework.CZBGEXos.js";const u=JSON.parse('{"title":"Terminal","description":"","frontmatter":{},"headers":[],"relativePath":"uk/tools/terminal.md","filePath":"uk/tools/terminal.md"}'),i={name:"uk/tools/terminal.md"};function d(l,t,o,s,p,c){return r(),e("div",null,[...t[0]||(t[0]=[n('<h1 id="terminal" tabindex="-1">Terminal <a class="header-anchor" href="#terminal" aria-label="Permalink to &quot;Terminal&quot;">​</a></h1><p>Terminal — це торговий термінал із глибиною ринку. Це єдиний інструмент Warden, який не лише читає дані: він підключається до вашого біржового акаунта за наданими вами ключами і розміщує, скасовує та закриває реальні ордери реальними коштами.</p><p>Він працює з п&#39;ятьма майданчиками на трьох біржах:</p><table tabindex="0"><thead><tr><th>Майданчик</th><th>Біржа</th><th>Ринок</th></tr></thead><tbody><tr><td>Hyperliquid</td><td>Hyperliquid</td><td>Безстрокові контракти</td></tr><tr><td>Binance Perp</td><td>Binance</td><td>Безстрокові ф&#39;ючерси</td></tr><tr><td>Binance Spot</td><td>Binance</td><td>Спот</td></tr><tr><td>Bybit Perp</td><td>Bybit</td><td>Безстрокові ф&#39;ючерси</td></tr><tr><td>Bybit Spot</td><td>Bybit</td><td>Спот</td></tr></tbody></table><div class="danger custom-block"><p class="custom-block-title">Це незавершений proof of concept</p><p>Terminal — тестовий інструмент, а не основний продукт. Він містить помилки, не є пріоритетом розробки й може поводитися непередбачувано. Підтримка Binance та Bybit новіша за Hyperliquid і відповідно менш перевірена.</p><p>Він також торгує реальними грошима:</p><ul><li><strong>Немає жодного підтвердження.</strong> Один клік по драбині цін миттєво надсилає ордер. Немає ані «ви впевнені?», ані попереднього перегляду, ані скасування.</li><li><strong>Потрібні торгові ключі</strong> — приватний ключ підписувача на Hyperliquid, API ключ і секрет із дозволом на торгівлю на Binance та Bybit.</li><li><strong>Збитки реальні та незворотні.</strong></li></ul><p>Якщо ви все ж користуєтесь ним — використовуйте акаунт, який не шкода втратити, і спершу вивчіть поведінку кліків на мінімальному розмірі ордера.</p><p>Якщо ви прийшли до Warden заради моніторингу, цей інструмент вам не потрібен: решта Warden читає лише публічні дані, ніколи не запитує ключі й не може торгувати.</p></div><div class="warning custom-block"><p class="custom-block-title">Ніколи не вмикайте дозвіл на виведення коштів</p><p>Terminal потребує лише торгівлі. API ключ із правом виведення перетворює будь-яку помилку або витік на спустошений акаунт, а не на невдалу угоду.</p><p>Вказівки застосунку: <strong>Binance</strong> — потрібні «Enable Futures» та «Enable Spot &amp; Margin Trading»; <strong>Bybit</strong> — ключ уніфікованого акаунта з дозволом «Trade». В обох випадках виведення коштів вмикати не можна.</p></div><div class="warning custom-block"><p class="custom-block-title">Сторінку ще не перекладено</p><p>Повний опис налаштувань, ключів, клавіш і поведінки кліків наразі доступний лише англійською. Переклад українською готується.</p><p><strong><a href="/manual/en/tools/terminal.html">Читати англійською → Terminal</a></strong></p></div>',7)])])}const b=a(i,[["render",d]]);export{u as __pageData,b as default};
